"""User authentication: register/login validation, sessions, password reset."""
import re
import secrets
import threading
import time
from functools import wraps

from flask import flash, redirect, request, session, url_for
from werkzeug.security import check_password_hash, generate_password_hash

import db

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
RESET_TTL_SECONDS = 30 * 60

# token -> (user_id, expires_at). In-memory on purpose: tokens are
# short-lived and must not survive a restart.
_reset_tokens = {}
_reset_lock = threading.Lock()


def hash_password(password):
    return generate_password_hash(password, method="pbkdf2:sha256")


def verify_password(password_hash, password):
    return check_password_hash(password_hash, password)


def validate_email(email):
    return bool(email) and bool(EMAIL_RE.match(email))


def validate_password(password):
    """Password policy: at least 8 characters."""
    return bool(password) and len(password) >= 8


def register_user(email, password):
    """Returns (user_id, error_message)."""
    email = (email or "").strip().lower()
    if not validate_email(email):
        return None, "邮箱格式不正确"
    if not validate_password(password):
        return None, "密码至少 8 位"
    if db.find_user_by_email(email):
        return None, "该邮箱已注册"
    user_id = db.create_user(email, hash_password(password))
    return user_id, None


def login_user(email, password):
    """Returns (user_row, error_message)."""
    email = (email or "").strip().lower()
    user = db.find_user_by_email(email)
    if not user or not verify_password(user["password_hash"], password):
        return None, "邮箱或密码错误"
    return user, None


def current_user():
    """Freshly loaded user row for the session, or None."""
    user_id = session.get("user_id")
    if not user_id:
        return None
    user = db.find_user(user_id)
    if not user:
        session.clear()
        return None
    return db.reset_unlimited_if_new_month(user)


def login_required(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        if not session.get("user_id"):
            flash("请先登录", "error")
            return redirect(url_for("login", next=request.path))
        return view(*args, **kwargs)

    return wrapped


# ---------------------------------------------------------------- reset flow

def create_reset_token(email):
    """Returns (token, error_message). Tokens are valid for 30 minutes."""
    user = db.find_user_by_email((email or "").strip().lower())
    if not user:
        return None, "该邮箱未注册"
    token = secrets.token_urlsafe(24)
    with _reset_lock:
        # Drop expired tokens opportunistically.
        now = time.time()
        for t in [t for t, (_, exp) in _reset_tokens.items() if exp < now]:
            _reset_tokens.pop(t, None)
        _reset_tokens[token] = (user["id"], now + RESET_TTL_SECONDS)
    return token, None


def consume_reset_token(token, new_password):
    """Set a new password if the token is valid. Returns error_message."""
    if not validate_password(new_password):
        return "密码至少 8 位"
    with _reset_lock:
        entry = _reset_tokens.pop(token, None)
    if not entry or entry[1] < time.time():
        return "重置链接无效或已过期"
    db.update_password(entry[0], hash_password(new_password))
    return None

