"""Admin panel blueprint, protected by env-var credentials."""
import functools
import hmac
import os

from flask import (
    Blueprint, current_app, flash, redirect, render_template, request,
    session, url_for,
)

import db

admin_bp = Blueprint("admin", __name__, url_prefix="/admin")


def _admin_credentials():
    return (
        os.environ.get("ADMIN_EMAIL", ""),
        os.environ.get("ADMIN_PASSWORD", ""),
    )


def admin_required(view):
    @functools.wraps(view)
    def wrapped(*args, **kwargs):
        if not session.get("is_admin"):
            return redirect(url_for("admin.admin_login"))
        return view(*args, **kwargs)

    return wrapped


def storage_stats():
    """Total size and file count under the collected/ storage root."""
    root = current_app.config["COLLECTED_DIR"]
    total_size = 0
    total_files = 0
    for dirpath, _, filenames in os.walk(root):
        for name in filenames:
            try:
                total_size += os.path.getsize(os.path.join(dirpath, name))
                total_files += 1
            except OSError:
                continue
    return total_size, total_files


def human_size(num):
    for unit in ("B", "KB", "MB", "GB"):
        if num < 1024 or unit == "GB":
            return f"{num:.1f} {unit}" if unit != "B" else f"{num} B"
        num /= 1024.0
    return f"{num:.1f} GB"


@admin_bp.route("/login", methods=["GET", "POST"])
def admin_login():
    if request.method == "POST":
        email, password = [[REDACTED:PASSWORD]]
        given_email = request.form.get("email", "")
        given_password = [[REDACTED:PASSWORD]]"password", "")
        ok_email = email and hmac.compare_digest(email, given_email)
        ok_password = [[REDACTED:PASSWORD]] and hmac.compare_digest(password, given_password)
        if ok_email and ok_password:
            session["is_admin"] = True
            flash("管理员登录成功", "ok")
            return redirect(url_for("admin.dashboard"))
        flash("管理员邮箱或密码错误", "error")
    return render_template("admin/login.html")


@admin_bp.route("/logout")
def admin_logout():
    session.pop("is_admin", None)
    flash("已退出管理员登录", "ok")
    return redirect(url_for("admin.admin_login"))


@admin_bp.route("/")
@admin_required
def dashboard():
    total_size, total_files = storage_stats()
    total_cards, unused_cards = db.count_cards()
    return render_template(
        "admin/dashboard.html",
        total_size=human_size(total_size),
        total_files=total_files,
        total_cards=total_cards,
        unused_cards=unused_cards,
    )


@admin_bp.route("/generate", methods=["GET", "POST"])
@admin_required
def generate():
    generated = None
    card_type = request.form.get("card_type", "")
    if request.method == "POST":
        card_type = request.form.get("card_type", "")
        try:
            count = int(request.form.get("count", "0"))
        except ValueError:
            count = 0
        if card_type not in db.CARD_TYPES:
            flash("请选择有效卡种", "error")
        elif not 1 <= count <= 100:
            flash("数量必须在 1-100 之间", "error")
        else:
            generated = db.generate_codes(card_type, count)
            flash(f"已生成 {len(generated)} 个兑换码", "ok")
    return render_template(
        "admin/generate.html",
        card_types=db.CARD_TYPES,
        generated=generated,
        card_type=card_type,
    )


@admin_bp.route("/users")
@admin_required
def users():
    return render_template("admin/users.html", users=db.list_users_with_usage())


@admin_bp.route("/codes")
@admin_required
def codes():
    return render_template("admin/codes.html", cards=db.list_cards())


@admin_bp.route("/logs")
@admin_required
def logs():
    return render_template("admin/logs.html", logs=db.list_logs())

