    if request.method == "POST":
        email, password = [[REDACTED:PASSWORD]]
        given_email = request.form.get("email", "")
        given_password = [[REDACTED:PASSWORD]]"password", "")
        ok_email = email and hmac.compare_digest(email, given_email)
        ok_password = [[REDACTED:PASSWORD]] and hmac.compare_digest(password, given_password)
        if ok_email and ok_password:
            session["is_admin"] = True
            flash("管理员登录成功", "ok")
            return redirect(url_for("admin.dashboard"))
        flash("管理员邮箱或密码错误", "error")
    return render_template("admin/login.html")


