"""Admin panel blueprint, protected by env-var credentials."""
import functools
import hmac
import os

from flask import (
    Blueprint, current_app, flash, redirect, render_template, request,
    session, url_for,
)

import db
import auth

admin_bp = Blueprint("admin", __name__, url_prefix="/admin")


def _admin_credentials():
    return (
        os.environ.get("ADMIN_EMAIL", ""),
        os.environ.get("ADMIN_PASSWORD", ""),
    )


def admin_required(view):
    @functools.wraps(view)
    def wrapped(*args, **kwargs):
        if not session.get("is_admin"):
            return redirect(url_for("admin.admin_login"))
        return view(*args, **kwargs)

    return wrapped


def storage_stats():
    """Total size and file count under the collected/ storage root."""
    root = current_app.config["COLLECTED_DIR"]
    total_size = 0
    total_files = 0
    for dirpath, _, filenames in os.walk(root):
        for name in filenames:
            try:
                total_size += os.path.getsize(os.path.join(dirpath, name))
                total_files += 1
            except OSError:
                continue
    return total_size, total_files


def human_size(num):
    for unit in ("B", "KB", "MB", "GB"):
        if num < 1024 or unit == "GB":
            return f"{num:.1f} {unit}" if unit != "B" else f"{num} B"
        num /= 1024.0
    return f"{num:.1f} GB"


