@app.route("/pay/<order_id>/qr.png")
@auth.login_required
def pay_qr(order_id):
    """Dynamic Alipay QR for a pending order, cached on the order row."""
    order = _load_own_order(order_id)
    if not order or order["status"] != "pending":
        abort(404)
    import io

    import qrcode

    qr_code = order["qr_code"]
    if not qr_code:
        notify_url = os.environ.get("ALIPAY_NOTIFY_URL") or (
            request.host_url.rstrip("/") + url_for("alipay_notify")
        )
        qr_code, error = alipay.precreate(
            f"DocKit {db.CARD_TYPES[order['card_type']]}",
            order["id"],
            db.yuan(order["amount_cents"]),
            notify_url,
        )
        if not qr_code:
            abort(404)
        from contextlib import closing
        with closing(db.connect()) as conn:
            conn.execute(
                "UPDATE orders SET qr_code = ? WHERE id = ?", (qr_code, order["id"])
            )
            conn.commit()
    buf = io.BytesIO()
    qrcode.make(qr_code, box_size=8, border=2).save(buf, "PNG")
    buf.seek(0)
    return send_file(buf, mimetype="image/png", max_age=0)


