"""DocKit — 文档优化工具 SaaS. Flask entry point with all routes."""
import os
import re
import secrets
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from concurrent.futures import TimeoutError as FuturesTimeoutError
from datetime import datetime, timezone

from flask import (
    Flask, abort, flash, redirect, render_template, request, send_file,
    send_from_directory, session, url_for,
)
from werkzeug.middleware.proxy_fix import ProxyFix
from werkzeug.utils import secure_filename

import auth
import alipay
import db
from admin import admin_bp
from processor import ALLOWED_EXTENSIONS, process_document

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
COLLECTED_DIR = os.path.join(BASE_DIR, "collected")
UNLIMITED_MONTHLY_LIMIT = 30

db.load_env()

app = Flask(__name__)
app.config["SECRET_KEY"] = os.environ.get("SECRET_KEY") or secrets.token_hex(32)
app.config["MAX_CONTENT_LENGTH"] = 25 * 1024 * 1024  # matches nginx 25m
app.config["COLLECTED_DIR"] = COLLECTED_DIR
app.config["SESSION_COOKIE_HTTPONLY"] = True
app.config["SESSION_COOKIE_SAMESITE"] = "Lax"
# Trust the single nginx in front of us (X-Forwarded-For / -Proto) so the
# per-IP rate limiter sees real client IPs. Keep :5000 firewalled from the
# internet — direct access bypasses this header.
app.wsgi_app = ProxyFix(app.wsgi_app, x_for=1, x_proto=1)
app.register_blueprint(admin_bp)
app.jinja_env.globals["yuan"] = db.yuan
app.jinja_env.globals["alipay_ready"] = alipay.is_configured

# Bounded core execution: at most 2 concurrent jobs, each capped at 120s.
# A hung or pathological file then fails instead of pinning the 1C2G box.
# Note: on timeout the worker thread itself cannot be killed; the slot is
# freed so the service stays responsive, the stuck thread ends on its own.
CORE_POOL = ThreadPoolExecutor(max_workers=2, thread_name_prefix="core")
CORE_SLOTS = threading.BoundedSemaphore(2)
CORE_TIMEOUT_SECONDS = 120
CORE_QUEUE_WAIT_SECONDS = 60

# Stop accepting new jobs once stored output exceeds this, so the disk
# filling up cannot take the whole service down.
STORAGE_CAP_BYTES = int(os.environ.get("DOCKIT_STORAGE_CAP_MB", "5120")) * 1024 * 1024
_storage_cache = {"ts": 0.0, "bytes": 0}

_FILENAME_RE = re.compile(r"^[\w\u4e00-\u9fff.\- ]{1,120}$")


class CoreBusy(Exception):
    pass


class CoreTimeout(Exception):
    pass


# ---------------------------------------------------------------- helpers

def ts_dir_name():
    """Collision-free directory name for one processing job."""
    now = datetime.now(timezone.utc)
    return f"{now:%Y%m%d-%H%M%S}-{now.microsecond // 1000:03d}-{secrets.token_hex(3)}"


def file_extension(filename):
    return os.path.splitext(filename)[1].lower()


def _magic_ok(stream, ext):
    """Content sniff: extension must match the file's magic bytes."""
    head = stream.read(8)
    stream.seek(0)
    if not head:
        return False
    if ext == ".pdf":
        return head.startswith(b"%PDF-")
    if ext == ".png":
        return head.startswith(b"\x89PNG")
    if ext in (".jpg", ".jpeg"):
        return head.startswith(b"\xff\xd8\xff")
    return head.startswith(b"PK\x03\x04")  # docx/xlsx are zip containers


def validate_upload(file):
    """Returns (original_name, error_message)."""
    if not file or not file.filename:
        return None, "请选择要处理的文件"
    original = secure_filename(file.filename) or file.filename
    if not _FILENAME_RE.match(original):
        return None, "文件名包含不支持的字符"
    ext = file_extension(original)
    if ext not in ALLOWED_EXTENSIONS:
        return None, "不支持的文件类型（支持 pdf / docx / xlsx / png / jpg）"
    if not _magic_ok(file.stream, ext):
        return None, "文件内容与扩展名不符，或文件为空"
    return original, None


def storage_usage():
    """Total bytes under collected/, cached for 60s. Over-cap readings are
    never cached, so the service recovers as soon as space is freed."""
    now = time.time()
    stale = now - _storage_cache["ts"] > 60
    if stale or _storage_cache["bytes"] > STORAGE_CAP_BYTES:
        total = 0
        for dirpath, _, filenames in os.walk(COLLECTED_DIR):
            for name in filenames:
                try:
                    total += os.path.getsize(os.path.join(dirpath, name))
                except OSError:
                    continue
        _storage_cache.update(ts=now, bytes=total)
    return _storage_cache["bytes"]


def run_core(input_path, work_dir, mode):
    """Run process_document with a concurrency cap and a hard timeout."""
    if not CORE_SLOTS.acquire(timeout=CORE_QUEUE_WAIT_SECONDS):
        raise CoreBusy()
    try:
        future = CORE_POOL.submit(process_document, input_path, work_dir, mode)
        try:
            return future.result(timeout=CORE_TIMEOUT_SECONDS)
        except FuturesTimeoutError:
            future.cancel()
            raise CoreTimeout() from None
    finally:
        CORE_SLOTS.release()


def check_quota(user, premium):
    """Pre-check before processing. Returns error_message or None."""
    if user["unlimited"]:
        return None  # quota re-verified atomically at charge time
    if premium and user["premium_balance"] > 0:
        return None
    if user["balance"] > 0:
        return None
    return "次数已用完，请兑换新卡"


def charge_user(user, premium):
    """Deduct one use after successful processing. Returns error or None."""
    if user["unlimited"]:
        return None if db.charge_unlimited(user["id"]) else "本月无限卡次数已用完（30 次/月）"
    if premium and user["premium_balance"] > 0:
        return None if db.charge_premium(user["id"]) else "次数已用完，请兑换新卡"
    return None if db.charge_balance(user["id"]) else "次数已用完，请兑换新卡"


